import datetime

def next_billing_date(start: datetime.date, months_ahead: int) -> datetime.date:
    if not isinstance(start, datetime.date) or isinstance(start, datetime.datetime):
        raise TypeError("start must be a datetime.date")
    if not isinstance(months_ahead, int):
        raise TypeError("months_ahead must be an int")
    year = start.year + (start.month - 1 + months_ahead) // 12
    month = (start.month - 1 + months_ahead) % 12 + 1
    day = start.day
    if month == 12:
        next_month_first = datetime.date(year + 1, 1, 1)
    else:
        next_month_first = datetime.date(year, month + 1, 1)
    last_day = (next_month_first - datetime.timedelta(days=1)).day
    if day > last_day:
        day = last_day
    return datetime.date(year, month, day)
